import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.D3sJ1xc1.js";const h=JSON.parse('{"title":"📜 Regulament ANP (Română)","description":"","frontmatter":{},"headers":[],"relativePath":"regulament-anp.md","filePath":"regulament-anp.md"}'),n={name:"regulament-anp.md"};function l(o,e,u,c,p,s){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="📜-regulament-anp-romana" tabindex="-1">📜 Regulament ANP (Română) <a class="header-anchor" href="#📜-regulament-anp-romana" aria-label="Permalink to &quot;📜 Regulament ANP (Română)&quot;">​</a></h1><hr><h2 id="cap-1-regim-disciplinar-pentru-detinuti" tabindex="-1">CAP. 1 - REGIM DISCIPLINAR PENTRU DEȚINUȚI <a class="header-anchor" href="#cap-1-regim-disciplinar-pentru-detinuti" aria-label="Permalink to &quot;CAP. 1 - REGIM DISCIPLINAR PENTRU DEȚINUȚI&quot;">​</a></h2><h3 id="_1-1-aplicarea-sanctiunilor" tabindex="-1">1.1 Aplicarea sancțiunilor <a class="header-anchor" href="#_1-1-aplicarea-sanctiunilor" aria-label="Permalink to &quot;1.1 Aplicarea sancțiunilor&quot;">​</a></h3><p>Personalul cu funcții de conducere poate aplica sancțiuni disciplinare în funcție de gravitatea abaterilor săvârșite de deținuți.</p><hr><h3 id="_1-2-abateri-minore" tabindex="-1">1.2 Abateri minore <a class="header-anchor" href="#_1-2-abateri-minore" aria-label="Permalink to &quot;1.2 Abateri minore&quot;">​</a></h3><p>Abaterile minore pot fi sancționate cu <strong>10 - 20 luni suplimentare</strong>.</p><h4 id="exemple" tabindex="-1">Exemple <a class="header-anchor" href="#exemple" aria-label="Permalink to &quot;Exemple&quot;">​</a></h4><ul><li>Refuzul executării ordinelor personalului.</li><li>Provocarea conflictelor între deținuți.</li><li>Comportament agresiv față de alte persoane private de libertate.</li></ul><hr><h3 id="_1-3-abateri-medii" tabindex="-1">1.3 Abateri medii <a class="header-anchor" href="#_1-3-abateri-medii" aria-label="Permalink to &quot;1.3 Abateri medii&quot;">​</a></h3><p>Abaterile medii pot fi sancționate cu <strong>20 - 40 luni suplimentare</strong>.</p><h4 id="exemple-1" tabindex="-1">Exemple <a class="header-anchor" href="#exemple-1" aria-label="Permalink to &quot;Exemple&quot;">​</a></h4><ul><li>Insultarea personalului penitenciar.</li><li>Agresiuni repetate asupra altor persoane.</li><li>Vătămarea altor persoane private de libertate.</li></ul><hr><h3 id="_1-4-abateri-grave" tabindex="-1">1.4 Abateri grave <a class="header-anchor" href="#_1-4-abateri-grave" aria-label="Permalink to &quot;1.4 Abateri grave&quot;">​</a></h3><p>Abaterile grave pot fi sancționate cu <strong>40 - 60 luni suplimentare</strong>.</p><h4 id="exemple-2" tabindex="-1">Exemple <a class="header-anchor" href="#exemple-2" aria-label="Permalink to &quot;Exemple&quot;">​</a></h4><ul><li>Organizarea sau participarea la revolte.</li><li>Agresarea gravă a personalului penitenciar.</li><li>Participarea la acțiuni colective care pun în pericol securitatea penitenciarului.</li></ul><hr><h3 id="_1-5-evidenta-sanctiunilor" tabindex="-1">1.5 Evidența sancțiunilor <a class="header-anchor" href="#_1-5-evidenta-sanctiunilor" aria-label="Permalink to &quot;1.5 Evidența sancțiunilor&quot;">​</a></h3><h3 id="reguli" tabindex="-1">Reguli <a class="header-anchor" href="#reguli" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Orice sancțiune aplicată trebuie documentată.</li><li>Toate sancțiunile trebuie înregistrate în sistemele interne ale penitenciarului.</li></ul><hr><h2 id="cap-2-organizarea-detinutilor" tabindex="-1">CAP. 2 - ORGANIZAREA DEȚINUȚILOR <a class="header-anchor" href="#cap-2-organizarea-detinutilor" aria-label="Permalink to &quot;CAP. 2 - ORGANIZAREA DEȚINUȚILOR&quot;">​</a></h2><h3 id="_2-1-supravegherea-detinutilor" tabindex="-1">2.1 Supravegherea deținuților <a class="header-anchor" href="#_2-1-supravegherea-detinutilor" aria-label="Permalink to &quot;2.1 Supravegherea deținuților&quot;">​</a></h3><p>Activitățile desfășurate în penitenciar trebuie organizate astfel încât securitatea să fie menținută permanent.</p><h3 id="reguli-1" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-1" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Un agent poate supraveghea simultan maximum <strong>doi deținuți</strong>.</li><li>În cazul unui număr mare de persoane private de libertate, activitățile se desfășoară prin rotație.</li><li>Deținuții trebuie supravegheați permanent în timpul transporturilor.</li><li>Deținuții trebuie supravegheați permanent în timpul activităților desfășurate în exteriorul penitenciarului.</li></ul><hr><h3 id="_2-2-activitati-pentru-detinuti" tabindex="-1">2.2 Activități pentru deținuți <a class="header-anchor" href="#_2-2-activitati-pentru-detinuti" aria-label="Permalink to &quot;2.2 Activități pentru deținuți&quot;">​</a></h3><p>Deținuții cu un comportament exemplar pot beneficia de facilități suplimentare.</p><h3 id="reguli-2" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-2" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Pot participa la activități speciale aprobate de conducere.</li><li>Pot participa la programe de muncă în vederea reducerii pedepsei.</li><li>Participarea la aceste activități este decisă exclusiv de conducerea penitenciarului.</li></ul><hr><h2 id="cap-3-promovari" tabindex="-1">CAP. 3 - PROMOVĂRI <a class="header-anchor" href="#cap-3-promovari" aria-label="Permalink to &quot;CAP. 3 - PROMOVĂRI&quot;">​</a></h2><h3 id="_3-1-acordarea-promovarilor" tabindex="-1">3.1 Acordarea promovărilor <a class="header-anchor" href="#_3-1-acordarea-promovarilor" aria-label="Permalink to &quot;3.1 Acordarea promovărilor&quot;">​</a></h3><p>Promovările sunt analizate și aprobate exclusiv de conducerea Administrației Naționale a Penitenciarelor.</p><hr><h3 id="_3-2-agent-operativ-→-agent-operativ-sef" tabindex="-1">3.2 Agent Operativ → Agent Operativ Șef <a class="header-anchor" href="#_3-2-agent-operativ-→-agent-operativ-sef" aria-label="Permalink to &quot;3.2 Agent Operativ → Agent Operativ Șef&quot;">​</a></h3><h4 id="conditii" tabindex="-1">Condiții <a class="header-anchor" href="#conditii" aria-label="Permalink to &quot;Condiții&quot;">​</a></h4><ul><li>Minimum <strong>7 zile</strong> vechime.</li><li>Raport complet de activitate.</li><li>Fără sancțiuni active.</li><li>Implicare constantă în activitatea penitenciarului.</li></ul><hr><h3 id="_3-3-agent-operativ-sef-→-supervizor-penitenciar" tabindex="-1">3.3 Agent Operativ Șef → Supervizor Penitenciar <a class="header-anchor" href="#_3-3-agent-operativ-sef-→-supervizor-penitenciar" aria-label="Permalink to &quot;3.3 Agent Operativ Șef → Supervizor Penitenciar&quot;">​</a></h3><h4 id="conditii-1" tabindex="-1">Condiții <a class="header-anchor" href="#conditii-1" aria-label="Permalink to &quot;Condiții&quot;">​</a></h4><ul><li>Minimum <strong>21 de zile</strong> vechime.</li><li>Activitate constantă.</li><li>Raport complet de activitate.</li><li>Conduită profesională și exemplară.</li></ul><hr><h2 id="cap-4-transfer-catre-politie" tabindex="-1">CAP. 4 - TRANSFER CĂTRE POLIȚIE <a class="header-anchor" href="#cap-4-transfer-catre-politie" aria-label="Permalink to &quot;CAP. 4 - TRANSFER CĂTRE POLIȚIE&quot;">​</a></h2><h3 id="_4-1-conditii-de-transfer" tabindex="-1">4.1 Condiții de transfer <a class="header-anchor" href="#_4-1-conditii-de-transfer" aria-label="Permalink to &quot;4.1 Condiții de transfer&quot;">​</a></h3><p>Transferul către Departamentul de Poliție <strong>Legacy Of CLT</strong> este posibil doar pentru membrii care îndeplinesc toate condițiile impuse.</p><h4 id="conditii-2" tabindex="-1">Condiții <a class="header-anchor" href="#conditii-2" aria-label="Permalink to &quot;Condiții&quot;">​</a></h4><ul><li>Au demonstrat profesionalism și disciplină.</li><li>Nu dețin sancțiuni active.</li><li>Au recomandarea conducerii penitenciarului.</li><li>Îndeplinesc toate cerințele de recrutare ale Departamentului de Poliție.</li></ul><hr><h2 id="cap-5-dispozitii-finale" tabindex="-1">CAP. 5 - DISPOZIȚII FINALE <a class="header-anchor" href="#cap-5-dispozitii-finale" aria-label="Permalink to &quot;CAP. 5 - DISPOZIȚII FINALE&quot;">​</a></h2><h3 id="_5-1-aplicarea-regulamentului" tabindex="-1">5.1 Aplicarea regulamentului <a class="header-anchor" href="#_5-1-aplicarea-regulamentului" aria-label="Permalink to &quot;5.1 Aplicarea regulamentului&quot;">​</a></h3><p>Respectarea prezentului regulament este obligatorie pentru întreg personalul Administrației Naționale a Penitenciarelor.</p><h3 id="reguli-3" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-3" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Nerespectarea regulamentului poate atrage sancțiuni disciplinare.</li><li>Conducerea își rezervă dreptul de a interpreta regulamentul în funcție de fiecare situație.</li><li>Regulamentul poate fi modificat ori de câte ori este necesar pentru buna funcționare a instituției.</li></ul><hr><h2 id="📌-nota" tabindex="-1">📌 NOTĂ <a class="header-anchor" href="#📌-nota" aria-label="Permalink to &quot;📌 NOTĂ&quot;">​</a></h2><p>Scopul prezentului regulament este menținerea unui sistem penitenciar organizat, sigur și orientat către un <strong>Roleplay</strong> realist și profesionist.</p><p>Respectarea tuturor prevederilor este obligatorie pentru fiecare membru al <strong>ANP Legacy Of CLT</strong>.</p>',63)])])}const m=a(n,[["render",l]]);export{h as __pageData,m as default};
